    int rc=lab(in,out);
    int ok=rc==0 &&
      (fabs(out[0]-(0)) <= (1e-6+1e-6*fabs((double)(0)))) &&
      (fabs(out[1]-(0)) <= (1e-6+1e-6*fabs((double)(0)))) &&
      (fabs(out[2]-(1)) <= (1e-6+1e-6*fabs((double)(1))));
    printf("%s boundary\n",ok?"PASS":"FAIL");
    if(!ok) ++failed;
  }
  {
    double in[8]={0},out[8]={0};
    if(lab(NULL,out)!=-1) ++failed;
    if(lab(in,NULL)!=-1) ++failed;
    in[7]=NAN;
    if(lab(in,out)!=-1) ++failed;
    puts("Common guards checked: null inputs, null outputs, NaN");
  }
  return failed?1:0;
}
